{
  "title": "Compiler Front-End Foundations: From Source to Intermediate Representation",
  "learningObjectives": [
    "Define and distinguish between lexical analysis, parsing, and semantic analysis by explaining how each stage transforms raw text into structured program representations.",
    "Construct a mental model of how an abstract syntax tree is validated through semantic checks and symbol table lookups before lowering to an intermediate representation.",
    "Trace a single expression through the front-end pipeline by identifying tokenization, grammar rules, AST node creation, type verification, and final intermediate representation generation."
  ],
